from __future__ import annotations

import math
from typing import Any

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict[str, Any]:
    error = _validate(raw)
    if error is not None:
        return {"ok": False, "error": error}

    grid = raw["grid"]
    width: int = grid["width"]
    height: int = grid["height"]
    cell_size: int = grid["cell_size"]
    tolerance = cell_size // 2

    mode = raw.get("mode", "mean")

    sums: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    max_values: dict[tuple[int, int], int] = {}
    degraded: set[tuple[int, int]] = set()
    dropped = rejected = saturated = 0

    for obs in raw["observations"]:
        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        cell = _cell_for(obs["x"], obs["y"], cell_size, width, height, tolerance)
        if cell is None:
            dropped += 1
            continue

        if counts.get(cell, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue

        sums[cell] = sums.get(cell, 0) + obs["value"]
        counts[cell] = counts.get(cell, 0) + 1
        if obs["value"] > max_values.get(cell, -math.inf):
            max_values[cell] = obs["value"]
        if obs["quality"] < GOOD_QUALITY:
            degraded.add(cell)

    cells = _cell_rows(sums, counts, max_values, mode, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _validate(raw: object) -> str | None:
    """Return an error message for invalid input, or None if valid."""
    if not isinstance(raw, dict):
        return "malformed input"
    if any(name not in raw for name in ("grid", "observations", "fill_value")):
        return "missing field"

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return "bad grid"
    if any(name not in grid for name in ("width", "height", "cell_size")):
        return "bad grid"

    width, height, cell_size = grid["width"], grid["height"], grid["cell_size"]
    if not isinstance(width, int) or not 1 <= width <= MAX_DIM:
        return "bad width"
    if not isinstance(height, int) or not 1 <= height <= MAX_DIM:
        return "bad height"
    if not isinstance(cell_size, int) or cell_size < 1:
        return "bad cell size"
    if not isinstance(raw["fill_value"], int):
        return "bad fill value"
    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return "bad mode"

    observations = raw["observations"]
    if not isinstance(observations, list):
        return "bad observations"
    for obs in observations:
        if not isinstance(obs, dict):
            return "bad observation"
        for field in ("x", "y", "value", "quality"):
            if field not in obs or not isinstance(obs[field], int):
                return "bad observation"
        if not 0 <= obs["quality"] <= 100:
            return "bad observation"
    return None


def _cell_for(
    x: int,
    y: int,
    cell_size: int,
    width: int,
    height: int,
    tolerance: int,
) -> tuple[int, int] | None:
    """Map a position to a cell key, or None if it falls outside the grid."""
    if x < 0 or y < 0:
        return None

    col = x // cell_size
    if col >= width and x - width * cell_size >= tolerance:
        return None
    col = min(col, width - 1)

    row = y // cell_size
    if row >= height and y - height * cell_size >= tolerance:
        return None
    row = min(row, height - 1)

    return (row, col)


def _cell_rows(
    sums: dict,
    counts: dict,
    max_values: dict,
    mode: str,
    width: int,
    height: int,
    fill_value: int,
) -> list:
    return [
        [_cell_value(sums, counts, max_values, mode, (row, col), fill_value)
         for col in range(width)]
        for row in range(height)
    ]


def _cell_value(
    sums: dict,
    counts: dict,
    max_values: dict,
    mode: str,
    key: tuple[int, int],
    fill_value: int,
) -> int:
    if key not in counts:
        return fill_value
    if mode == "max":
        return max_values[key]
    return sums[key] // counts[key]


def _flag_rows(counts: dict, degraded: set, width: int, height: int) -> list:
    return [
        [_flag(counts, degraded, (row, col)) for col in range(width)]
        for row in range(height)
    ]


def _flag(counts: dict, degraded: set, key: tuple[int, int]) -> str:
    if key not in counts:
        return "empty"
    if key in degraded:
        return "degraded"
    return "good"


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(
    total_cells: int,
    filled: int,
    dropped: int,
    rejected: int,
    saturated: int,
    coverage: int,
) -> str:
    return (
        f"cells={total_cells}"
        f";filled={filled}"
        f";dropped={dropped}"
        f";rejected={rejected}"
        f";saturated={saturated}"
        f";coverage={coverage}"
    )

from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}

    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if _is_invalid_obs(obs):
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        col, ok = _map_axis(obs["x"], cell_size, width, tolerance)
        if not ok:
            dropped = dropped + 1
            continue
        row, ok = _map_axis(obs["y"], cell_size, height, tolerance)
        if not ok:
            dropped = dropped + 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        if mode == "max":
            if obs["value"] > sums.get(key, -10**9):
                sums[key] = obs["value"]
        else:
            sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells = _averaged_rows(sums, counts, width, height, raw["fill_value"], mode)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _is_invalid_obs(obs: object) -> bool:
    """True when an observation fails structural or range validation."""
    if not isinstance(obs, dict):
        return True
    for field in ("x", "y", "value", "quality"):
        if field not in obs or not isinstance(obs[field], int):
            return True
    return obs["quality"] < 0 or obs["quality"] > 100


def _map_axis(value: int, cell_size: int, limit: int, tolerance: int) -> tuple[int, bool]:
    """Map a coordinate to a cell index (0..limit-1) or signal it must be dropped.

    Coordinates past the last full cell are admitted into the final column/row
    when they fall within the tolerance band; anything further out is dropped.
    """
    if value < 0:
        return 0, False
    idx = value // cell_size
    if idx >= limit:
        if value - limit * cell_size < tolerance:
            idx = limit - 1
        else:
            return 0, False
    return idx, True


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int, mode: str) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                if mode == "max":
                    cells.append(sums[key])
                else:
                    cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    """Fuse per-cell observations into an aggregated grid report.

    Behavior contract (must never change):
      - reject malformed / missing / mistyped inputs with a {ok: False} error dict
      - per observation: reject when quality < MIN_QUALITY; drop when the
        coordinate falls outside the grid and the overshoot is not within
        tolerance; clip back on to the edge cell only when the overshoot is
        small; ignore once a cell has reached SATURATION_LIMIT samples
      - mark a cell "degraded" if any accepted sample had quality < GOOD_QUALITY
      - report counts for dropped/rejected/saturated and integer percentage coverage
      - "mode" is optional; "mean" (default) averages, "max" reports the
        highest observed value per filled cell; anything else is an error
    """
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}

    sums: dict[tuple[int, int], int] = {}
    maxs: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    degraded: dict[tuple[int, int], bool] = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation"}
        if "x" not in obs or not isinstance(obs["x"], int):
            return {"ok": False, "error": "bad observation"}
        if "y" not in obs or not isinstance(obs["y"], int):
            return {"ok": False, "error": "bad observation"}
        if "value" not in obs or not isinstance(obs["value"], int):
            return {"ok": False, "error": "bad observation"}
        if "quality" not in obs or not isinstance(obs["quality"], int):
            return {"ok": False, "error": "bad observation"}
        if obs["quality"] < 0 or obs["quality"] > 100:
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        # Project observation onto the grid, clipping small edge overshoots.
        col = _project(obs["x"], cell_size, width, tolerance)
        if col is None:
            dropped += 1
            continue
        row = _project(obs["y"], cell_size, height, tolerance)
        if row is None:
            dropped += 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        if mode == "max":
            current = maxs.get(key)
            if current is None or obs["value"] > current:
                maxs[key] = obs["value"]
        else:
            sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    if mode == "max":
        cells = _max_rows(maxs, counts, width, height, raw["fill_value"])
    else:
        cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _project(value: int, cell_size: int, limit: int, tolerance: int) -> int | None:
    """Map a coordinate to a cell index, or None when it must be dropped.

    Negative coordinates and overshoots beyond tolerance are dropped; a small
    overshoot past the far edge is clipped onto the last cell.
    """
    if value < 0:
        return None
    index = value // cell_size
    if index < limit:
        return index
    if value - limit * cell_size < tolerance:
        return limit - 1
    return None


def _averaged_rows(
    sums: dict[tuple[int, int], int],
    counts: dict[tuple[int, int], int],
    width: int,
    height: int,
    fill_value: int,
) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _max_rows(
    maxs: dict[tuple[int, int], int],
    counts: dict[tuple[int, int], int],
    width: int,
    height: int,
    fill_value: int,
) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(maxs[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(
    counts: dict[tuple[int, int], int],
    degraded: dict[tuple[int, int], bool],
    width: int,
    height: int,
) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict[tuple[int, int], int], width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(
    total_cells: int,
    filled: int,
    dropped: int,
    rejected: int,
    saturated: int,
    coverage: int,
) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

