"""Accumulate spatial observations into a regular grid of cells.

Observations are binned by cell index (``x // cell_size``, ``y // cell_size``),
subject to a half-cell tolerance that snaps points just past the final edge into
the edge cells. Each cell stores the integer average of contributing values and
a quality flag. Low-quality observations are rejected outright; points outside
the grid are dropped; cells may be filled only up to a saturation limit.
"""

from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    """Return a per-cell summary of the observations described by ``raw``.

    ``raw`` is expected to contain ``grid`` (``{width, height, cell_size}``),
    ``observations`` (a list of ``{x, y, value, quality}``), ``fill_value``,
    and optionally ``mode`` (``"mean"`` or ``"max"``; defaults to ``"mean"``).

    Returns ``{"ok": False, "error": ...}`` on malformed input, or a success
    dict with ``cells``, ``flags``, counters, ``coverage`` and a ``line``
    summary. External callers rely on the exact error strings and counters.
    """
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if not all(k in raw for k in ("grid", "observations", "fill_value")):
        return {"ok": False, "error": "missing field"}

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if not all(k in grid for k in ("width", "height", "cell_size")):
        return {"ok": False, "error": "bad grid"}

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}

    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}

    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    # Precomputed bounds so the inner loop avoids repeated multiplications.
    right_edge = width * cell_size
    bottom_edge = height * cell_size
    tolerance = cell_size // 2

    sums = {}
    maxes = {}
    counts = {}
    degraded = set()
    dropped = 0
    rejected = 0
    saturated = 0

    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation"}
        if not isinstance(obs.get("x"), int):
            return {"ok": False, "error": "bad observation"}
        if not isinstance(obs.get("y"), int):
            return {"ok": False, "error": "bad observation"}
        if not isinstance(obs.get("value"), int):
            return {"ok": False, "error": "bad observation"}
        if not isinstance(obs.get("quality"), int):
            return {"ok": False, "error": "bad observation"}

        # Required on the raw dict membership, not on the (possibly absent) get.
        x = obs["x"]
        y = obs["y"]
        value = obs["value"]
        quality = obs["quality"]
        if quality < 0 or quality > 100:
            return {"ok": False, "error": "bad observation"}

        if quality < MIN_QUALITY:
            rejected += 1
            continue

        if x < 0:
            dropped += 1
            continue
        col = x // cell_size
        if col >= width:
            # Snap points inside the trailing tolerance window into the last column.
            if x - right_edge < tolerance:
                col = width - 1
            else:
                dropped += 1
                continue

        if y < 0:
            dropped += 1
            continue
        row = y // cell_size
        if row >= height:
            if y - bottom_edge < tolerance:
                row = height - 1
            else:
                dropped += 1
                continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + value
        maxes[key] = max(maxes.get(key, value), value)
        counts[key] = counts.get(key, 0) + 1
        if quality < GOOD_QUALITY:
            degraded.add(key)

    total_cells = width * height
    cells = _averaged_rows(sums, maxes, counts, mode, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, total_cells)
    line = _summary_line(total_cells, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
