        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        if mode == "mean":
            sums[key] = sums.get(key, 0) + obs["value"]
        else:
            if key in maxs:
                maxs[key] = max(maxs[key], obs["value"])
            else:
                maxs[key] = obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    values = sums if mode == "mean" else maxs
    cells = _cell_rows(values, counts, width, height, raw["fill_value"], mode)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _project(coord: int, cell_size: int, dim: int) -> int | None:
    """Map a coordinate to a grid index, or None if it should be dropped.

    Coordinates are floor-divided by the cell size. Values slightly beyond the
    far edge (within half a cell) clamp to the last index; everything else is
    dropped.
    """
    if coord < 0:
        return None
    index = coord // cell_size
    if index >= dim:
        if coord - dim * cell_size < cell_size // 2:
            return dim - 1
        return None
    return index


def _cell_rows(values: dict, counts: dict, width: int, height: int, fill_value: int, mode: str) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                value = values[key]
                if mode == "mean":
                    value = value // counts[key]
                cells.append(value)
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        f"cells={total_cells}"
        f";filled={filled}"
        f";dropped={dropped}"
        f";rejected={rejected}"
        f";saturated={saturated}"
        f";coverage={coverage}"
    )

from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

# Cell key = (row, col). Internal totals only need per-cell ints.
CellKey = tuple[int, int]


def accumulate_grid(raw: object, mode: str = "mean") -> dict:
    """Accumulate observations onto a fixed grid.

    Returns {"ok": True, ...} on success or a {"ok": False, "error": ...}
    dict on malformed input. Values in each cell summarize the accepted
    observations binned to it: "mean" is the integer mean, "max" is the
    highest observed value. Unrecognized modes are a validation error.
    """
    if mode not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    sums: dict[CellKey, int] = {}
    maxs: dict[CellKey, int] = {}
    counts: dict[CellKey, int] = {}
    degraded: dict[CellKey, bool] = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation"}
        if "x" not in obs or not isinstance(obs["x"], int):
            return {"ok": False, "error": "bad observation"}
        if "y" not in obs or not isinstance(obs["y"], int):
            return {"ok": False, "error": "bad observation"}
        if "value" not in obs or not isinstance(obs["value"], int):
            return {"ok": False, "error": "bad observation"}
        if "quality" not in obs or not isinstance(obs["quality"], int):
            return {"ok": False, "error": "bad observation"}
        if obs["quality"] < 0 or obs["quality"] > 100:
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        x = obs["x"]
        if x < 0:
            dropped = dropped + 1
            continue
        col = x // cell_size
        if col >= width:
            if x - width * cell_size < tolerance:
                col = width - 1
            else:
                dropped = dropped + 1
                continue

        y = obs["y"]
        if y < 0:
            dropped = dropped + 1
            continue
        row = y // cell_size
        if row >= height:
            if y - height * cell_size < tolerance:
                row = height - 1
            else:
                dropped = dropped + 1
                continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        if counts.get(key, 0) == 0:
            maxs[key] = obs["value"]
        elif obs["value"] > maxs[key]:
            maxs[key] = obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    if mode == "max":
        cells = _max_rows(maxs, counts, width, height, raw["fill_value"])
    else:
        cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _averaged_rows(
    sums: dict[CellKey, int],
    counts: dict[CellKey, int],
    width: int,
    height: int,
    fill_value: int,
) -> list[list[int]]:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _max_rows(
    maxs: dict[CellKey, int],
    counts: dict[CellKey, int],
    width: int,
    height: int,
    fill_value: int,
) -> list[list[int]]:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(maxs[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(
    counts: dict[CellKey, int],
    degraded: dict[CellKey, bool],
    width: int,
    height: int,
) -> list[list[str]]:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict[CellKey, int], width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(
    total_cells: int,
    filled: int,
    dropped: int,
    rejected: int,
    saturated: int,
    coverage: int,
) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

