from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90, "student": 20}

_PAYOUT_STATES = {
    "active": {"status": "renewed", "fee": lambda t: TIER_FEES[t]},
    "lapsed": {
        "status": None,  # determined by expired_days
        "fee": lambda t, d: TIER_FEES[t]
        + (LATE_FEE if d <= GRACE_DAYS else REINSTATE_SURCHARGE),
    },
    "suspended": {
        "status": "reactivated",
        "fee": lambda t: TIER_FEES[t] + TIER_FEES[t] // 2,
    },
}


def _validate_shape(member: dict, payment: dict) -> tuple[bool, str]:
    if "id" not in member or "status" not in member or "tier" not in member:
        return False, "missing member field"
    if "amount" not in payment or "method" not in payment:
        return False, "missing payment field"
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return False, "bad member id"
    return True, ""


def _validate_payment(payment: dict) -> tuple[bool, str]:
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return False, "bad amount"
    if payment["method"] not in ("card", "transfer"):
        return False, "unsupported method"
    return True, ""


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    member = raw_member
    payment = raw_payment

    ok, err = _validate_shape(member, payment)
    if not ok:
        return {"ok": False, "error": err}

    status = member["status"]
    if status == "banned":
        return {"ok": False, "error": "member banned"}
    if status not in _PAYOUT_STATES:
        return {"ok": False, "error": "unknown status"}
    if member["tier"] not in TIER_FEES:
        return {"ok": False, "error": "unknown tier"}

    # Branch-specific validation.
    if status == "lapsed":
        expired = member.get("expired_days")
        if not isinstance(expired, int) or expired < 0:
            return {"ok": False, "error": "bad expiry"}
        payout_status = "renewed" if expired <= GRACE_DAYS else "reinstated"
    elif status == "suspended":
        strikes = member.get("strikes")
        if not isinstance(strikes, int) or strikes < 0:
            return {"ok": False, "error": "bad strikes"}
        if strikes >= MAX_STRIKES:
            return {"ok": False, "error": "too many strikes"}
        payout_status = "reactivated"
    else:  # active
        payout_status = "renewed"

    ok, err = _validate_payment(payment)
    if not ok:
        return {"ok": False, "error": err}

    if status == "lapsed":
        fee = _PAYOUT_STATES[status]["fee"](member["tier"], expired)
    else:
        fee = _PAYOUT_STATES[status]["fee"](member["tier"])
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}

    receipt = "{}:{}:{}:{}".format(
        payment["method"], member["id"], payout_status, fee
    )
    return {"ok": True, "status": payout_status, "fee": fee, "receipt": receipt}

