"""Accumulate point observations into a uniform grid and report per-cell stats.

Public entry point is ``accumulate_grid``. Validation errors are reported as
``{"ok": False, "error": <reason>}`` and never raise.
"""

from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def _expect_type(raw, field: str, check) -> str | None:
    """Return an error string if ``raw[field]`` fails ``check``, else None."""
    value = raw.get(field)
    if value is None or not check(value):
        return field
    return None


def _validate(raw) -> tuple | str:
    """Validate the full request. Returns ``(grid, observations, fill_value)``
    or an error string."""
    if not isinstance(raw, dict):
        return "malformed input"
    if any(f not in raw for f in ("grid", "observations", "fill_value")):
        return "missing field"

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return "bad grid"
    if any(f not in grid for f in ("width", "height", "cell_size")):
        return "bad grid"

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or not 1 <= width <= MAX_DIM:
        return "bad width"
    if not isinstance(height, int) or not 1 <= height <= MAX_DIM:
        return "bad height"
    if not isinstance(cell_size, int) or cell_size < 1:
        return "bad cell size"
    if not isinstance(raw["fill_value"], int):
        return "bad fill value"

    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return "bad mode"

    observations = raw["observations"]
    if not isinstance(observations, list):
        return "bad observations"
    return grid, observations, raw["fill_value"], mode


def _observation_error(obs) -> str | None:
    """Return an error string for a malformed observation, else None."""
    if not isinstance(obs, dict):
        return "bad observation"
    for field, check in (
        ("x", lambda v: isinstance(v, int)),
        ("y", lambda v: isinstance(v, int)),
        ("value", lambda v: isinstance(v, int)),
        ("quality", lambda v: isinstance(v, int)),
    ):
        value = obs.get(field)
        if value is None or not check(value):
            return "bad observation"
    if not 0 <= obs["quality"] <= 100:
        return "bad observation"
    return None


def accumulate_grid(raw: object) -> dict:
    parsed = _validate(raw)
    if isinstance(parsed, str):
        return {"ok": False, "error": parsed}
    grid, observations, fill_value, mode = parsed
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    tolerance = cell_size // 2

    sums = {}
    counts = {}
    maxes = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0

    for obs in observations:
        err = _observation_error(obs)
        if err:
            return {"ok": False, "error": err}

        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        col = _bin(obs["x"], width, cell_size, tolerance)
        row = _bin(obs["y"], height, cell_size, tolerance)
        if col is None or row is None:
            dropped += 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        if mode == "max":
            if key not in maxes or obs["value"] > maxes[key]:
                maxes[key] = obs["value"]
        else:
            sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    total_cells = width * height
    cells = _cell_rows(sums, counts, maxes, mode, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, total_cells)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": _summary_line(total_cells, len(counts), dropped, rejected, saturated, coverage),
    }


def _bin(coord: int, dim: int, cell_size: int, tolerance: int) -> int | None:
    """Bin a coordinate into a cell index, clamping edge-hugging values or
    returning None to drop out-of-range coordinates."""
    if coord < 0:
        return None
    index = coord // cell_size
    if index >= dim:
        if coord - dim * cell_size < tolerance:
            return dim - 1
        return None
    return index


def _cell_rows(sums: dict, counts: dict, maxes: dict, mode: str, width: int, height: int, fill_value: int) -> list:
    if mode == "max":
        return _max_rows(maxes, counts, width, height, fill_value)
    return _averaged_rows(sums, counts, width, height, fill_value)


def _max_rows(maxes: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    return [
        [maxes[(row, col)] if (row, col) in counts else fill_value
         for col in range(width)]
        for row in range(height)
    ]


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    return [
        [sums[(row, col)] // counts[(row, col)] if (row, col) in counts else fill_value
         for col in range(width)]
        for row in range(height)
    ]


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    return [
        ["empty" if (row, col) not in counts
         else "degraded" if (row, col) in degraded
         else "good"
         for col in range(width)]
        for row in range(height)
    ]


def _coverage(counts: dict, total_cells: int) -> int:
    return len(counts) * 100 // total_cells


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    parts = (
        f"cells={total_cells}",
        f"filled={filled}",
        f"dropped={dropped}",
        f"rejected={rejected}",
        f"saturated={saturated}",
        f"coverage={coverage}",
    )
    return ";".join(parts)

from __future__ import annotations

from dataclasses import dataclass, field

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


@dataclass
class _CellAccumulator:
    """Running aggregate for one grid cell."""

    total: int = 0
    count: int = 0
    maximum: int = 0
    degraded: bool = False


def _fail(error: str) -> dict:
    """Build a uniform failure result."""
    return {"ok": False, "error": error}


def _clamp_index(coord: int, size: int, cell_size: int) -> tuple[int, bool]:
    """Map a coordinate to a cell index, keeping near-edge points.

    Returns (index, ok). ok is False when the coordinate lies too far past the
    outer edge (or is negative) and the observation must be dropped.
    """
    if coord < 0:
        return 0, False
    idx = coord // cell_size
    if idx < size:
        return idx, True
    # Past the last cell: keep only points within half a cell of the edge.
    if coord - size * cell_size < cell_size // 2:
        return size - 1, True
    return 0, False


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return _fail("malformed input")
    if not {"grid", "observations", "fill_value"} <= set(raw):
        return _fail("missing field")

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return _fail("bad grid")
    if not {"width", "height", "cell_size"} <= set(grid):
        return _fail("bad grid")

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return _fail("bad width")
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return _fail("bad height")
    if not isinstance(cell_size, int) or cell_size < 1:
        return _fail("bad cell size")
    if not isinstance(raw["fill_value"], int):
        return _fail("bad fill value")

    observations = raw["observations"]
    if not isinstance(observations, list):
        return _fail("bad observations")

    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return _fail("bad mode")

    cells: dict[tuple[int, int], _CellAccumulator] = {}
    dropped = rejected = saturated = 0

    for obs in observations:
        if not isinstance(obs, dict):
            return _fail("bad observation")
        if "x" not in obs or not isinstance(obs["x"], int):
            return _fail("bad observation")
        if "y" not in obs or not isinstance(obs["y"], int):
            return _fail("bad observation")
        if "value" not in obs or not isinstance(obs["value"], int):
            return _fail("bad observation")
        if "quality" not in obs or not isinstance(obs["quality"], int):
            return _fail("bad observation")
        if obs["quality"] < 0 or obs["quality"] > 100:
            return _fail("bad observation")

        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        col, ok = _clamp_index(obs["x"], width, cell_size)
        if not ok:
            dropped += 1
            continue
        row, ok = _clamp_index(obs["y"], height, cell_size)
        if not ok:
            dropped += 1
            continue

        key = (row, col)
        acc = cells.get(key)
        if acc is None:
            acc = cells[key] = _CellAccumulator()
        if acc.count >= SATURATION_LIMIT:
            saturated += 1
            continue
        acc.total += obs["value"]
        if obs["value"] > acc.maximum:
            acc.maximum = obs["value"]
        acc.count += 1
        if obs["quality"] < GOOD_QUALITY:
            acc.degraded = True

    grid_cells = _cell_rows(cells, width, height, raw["fill_value"], mode)
    flags = _flag_rows(cells, width, height)
    coverage = _coverage(cells, width, height)
    filled = len(cells)
    line = _summary_line(width * height, filled, dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": grid_cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _cell_rows(cells: dict, width: int, height: int, fill_value: int, mode: str) -> list:
    rows = []
    for row in range(height):
        cell_row = []
        for col in range(width):
            acc = cells.get((row, col))
            if acc is None:
                cell_row.append(fill_value)
            elif mode == "max":
                cell_row.append(acc.maximum)
            else:
                cell_row.append(acc.total // acc.count)
        rows.append(cell_row)
    return rows


def _flag_rows(cells: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flag_row = []
        for col in range(width):
            acc = cells.get((row, col))
            if acc is None:
                flag_row.append("empty")
            elif acc.degraded:
                flag_row.append("degraded")
            else:
                flag_row.append("good")
        rows.append(flag_row)
    return rows


def _coverage(cells: dict, width: int, height: int) -> int:
    return len(cells) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

