from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90, "student": 20}
VALID_METHODS = {"card", "transfer"}


def _check_tier(member: dict) -> str | None:
    return None if member["tier"] in TIER_FEES else "unknown tier"


def _check_amount(payment: dict) -> str | None:
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    return None


def _check_method(payment: dict) -> str | None:
    return None if payment["method"] in VALID_METHODS else "unsupported method"


def _check_non_negative_int(member: dict, field: str, error: str) -> str | None:
    if field not in member or not isinstance(member[field], int) or member[field] < 0:
        return error
    return None


def _receipt(payment: dict, member: dict, status: str, fee: int) -> str:
    return f"{payment['method']}:{member['id']}:{status}:{fee}"


def _error(kind: str) -> dict:
    return {"ok": False, "error": kind}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return _error("malformed input")
    member = raw_member
    payment = raw_payment
    if "id" not in member or "status" not in member or "tier" not in member:
        return _error("missing member field")
    if "amount" not in payment or "method" not in payment:
        return _error("missing payment field")
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return _error("bad member id")

    status = member["status"]
    if status == "banned":
        return _error("member banned")

    if status == "active":
        if (err := _check_tier(member)):
            return _error(err)
        if (err := _check_amount(payment)):
            return _error(err)
        if (err := _check_method(payment)):
            return _error(err)
    elif status == "lapsed":
        if (err := _check_tier(member)):
            return _error(err)
        if (err := _check_non_negative_int(member, "expired_days", "bad expiry")):
            return _error(err)
        if (err := _check_amount(payment)):
            return _error(err)
        if (err := _check_method(payment)):
            return _error(err)
    elif status == "suspended":
        if (err := _check_tier(member)):
            return _error(err)
        if (err := _check_non_negative_int(member, "strikes", "bad strikes")):
            return _error(err)
        if member["strikes"] >= MAX_STRIKES:
            return _error("too many strikes")
        if (err := _check_amount(payment)):
            return _error(err)
        if (err := _check_method(payment)):
            return _error(err)
    else:
        return _error("unknown status")

    tier = member["tier"]
    if status == "active":
        fee = TIER_FEES[tier]
        new_status = "renewed"
    elif status == "lapsed":
        if member["expired_days"] <= GRACE_DAYS:
            fee = TIER_FEES[tier] + LATE_FEE
            new_status = "renewed"
        else:
            fee = TIER_FEES[tier] + REINSTATE_SURCHARGE
            new_status = "reinstated"
    else:  # suspended
        fee = TIER_FEES[tier] + TIER_FEES[tier] // 2
        new_status = "reactivated"

    if payment["amount"] < fee:
        return _error("insufficient payment")

    return {"ok": True, "status": new_status, "fee": fee, "receipt": _receipt(payment, member, new_status, fee)}

from __future__ import annotations

GRACE_DAYS = 30
