VALID_METHODS = {"card", "transfer"}
SUSPENDED_SURCHARGE_MULTIPLIER = 1.5


def _tier_fee(tier: str) -> int | None:
    return TIER_FEES.get(tier)


def _validate_member_and_payment(member: object, payment: object) -> str | None:
    """Return an error message, or None if member/payment structure is sound.

    Checks that mirror the original code up to (and including) the tier check.
    Per-status field and payment validation happens later to preserve error
    precedence.
    """
    if not isinstance(member, dict) or not isinstance(payment, dict):
        return "malformed input"
    if "id" not in member or "status" not in member or "tier" not in member:
        return "missing member field"
    if "amount" not in payment or "method" not in payment:
        return "missing payment field"
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return "bad member id"
    if member["status"] == "banned":
        return "member banned"
    if member["status"] not in ("active", "lapsed", "suspended"):
        return "unknown status"
    if _tier_fee(member["tier"]) is None:
        return "unknown tier"
    return None


def _validate_payment(member: dict, payment: dict) -> str | None:
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    if payment["method"] not in VALID_METHODS:
        return "unsupported method"
    return None


def _apply_status(member: dict, payment: dict, status: str, fee: int) -> dict:
    if payment["method"] == "card":
        receipt = "card:" + member["id"] + ":" + status + ":" + str(fee)
    else:
        receipt = "transfer:" + member["id"] + ":" + status + ":" + str(fee)
    return {"ok": True, "status": status, "fee": fee, "receipt": receipt}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    error = _validate_member_and_payment(raw_member, raw_payment)
    if error:
        return {"ok": False, "error": error}

    member = raw_member
    payment = raw_payment
    status = member["status"]

    if status == "active":
        fee = _tier_fee(member["tier"])
        error = _validate_payment(member, payment)
        if error:
            return {"ok": False, "error": error}
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        return _apply_status(member, payment, "renewed", fee)

    if status == "lapsed":
        if "expired_days" not in member or not isinstance(member["expired_days"], int) or member["expired_days"] < 0:
            return {"ok": False, "error": "bad expiry"}
        fee = _tier_fee(member["tier"])
        if member["expired_days"] <= GRACE_DAYS:
            fee += LATE_FEE
            new_status = "renewed"
        else:
            fee += REINSTATE_SURCHARGE
            new_status = "reinstated"
        error = _validate_payment(member, payment)
        if error:
            return {"ok": False, "error": error}
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        return _apply_status(member, payment, new_status, fee)

    if status == "suspended":
        if "strikes" not in member or not isinstance(member["strikes"], int) or member["strikes"] < 0:
            return {"ok": False, "error": "bad strikes"}
        if member["strikes"] >= MAX_STRIKES:
            return {"ok": False, "error": "too many strikes"}
        fee = int(_tier_fee(member["tier"]) * SUSPENDED_SURCHARGE_MULTIPLIER)
        error = _validate_payment(member, payment)
        if error:
            return {"ok": False, "error": error}
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        return _apply_status(member, payment, "reactivated", fee)

    # Unreachable: _validate_member_and_payment rejects any other status.
    return {"ok": False, "error": "unknown status"}

