export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategorySpec {
  name: string;
  baseRate: number;
  highRate: number;
  nights: readonly [number, number];
  maxGuests: number;
  minStay?: number;
  surcharge?: number;
  fee?: number;
}

const SPECS: Record<string, CategorySpec> = {
  standard: { name: "standard", baseRate: 80, highRate: 110, nights: [1, 14], maxGuests: 2 },
  suite: { name: "suite", baseRate: 150, highRate: 210, nights: [1, 21], maxGuests: 4, surcharge: 25 },
  villa: { name: "villa", baseRate: 300, highRate: 420, nights: [1, 28], maxGuests: 8, minStay: 3, fee: 500 },
  cabin: { name: "cabin", baseRate: 50, highRate: 65, nights: [1, 10], maxGuests: 6 },
};

function isIntInRange(v: unknown, lo: number, hi: number): boolean {
  return Number.isInteger(v) && (v as number) >= lo && (v as number) <= hi;
}

function invalid(reason: string): QuoteResult {
  return { ok: false, error: reason };
}

function totalFor(spec: CategorySpec, nights: number, guests: number, vip: boolean, high: boolean): number {
  const rate = high ? spec.highRate : spec.baseRate;
  let total = rate * nights;
  if (vip) total -= Math.floor(total / 10);
  if (spec.surcharge !== undefined && guests > 2) total += spec.surcharge;
  if (spec.fee !== undefined) total += spec.fee;
  return total;
}

function validate(spec: CategorySpec, req: Record<string, unknown>): string | undefined {
  const nights = req.nights as number;
  const guests = req.guests as number;
  const season = req.season as string;

  if (!isIntInRange(nights, spec.nights[0], spec.nights[1])) return "bad nights";
  if (spec.minStay !== undefined && nights < spec.minStay) return "villa minimum stay";
  if (!isIntInRange(guests, 1, spec.maxGuests)) return "bad guests";
  if (season !== "low" && season !== "high") return "bad season";
  return undefined;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) return invalid("malformed request");
  const req = raw as Record<string, unknown>;
  if (!isIntInRange(req.loyaltyYears, 0, Infinity)) return invalid("bad loyalty");

  const spec = SPECS[req.category as string];
  if (spec === undefined) return invalid("unknown category");

  const problem = validate(spec, req);
  if (problem !== undefined) return invalid(problem);

  const nights = req.nights as number;
  const guests = req.guests as number;
  const vip = req.coupon === "VIP" || (req.loyaltyYears as number) >= 3;
  const total = totalFor(spec, nights, guests, vip, req.season === "high");
  const policy = vip ? "flex" : "strict";
  return { ok: true, total, policy, line: `${spec.name}:${nights}n:${total}:${policy}` };
}

