    return None


def _count_gaps(timestamps: list, expected_step: int) -> int:
    gaps = 0
    for index in range(1, len(timestamps)):
        if timestamps[index] - timestamps[index - 1] > expected_step:
            gaps += 1
    return gaps


def _deviations(values: list) -> list:
    deviations = []
    for index in range(len(values)):
        deviations.append(abs(values[index] - _window_median(values, index)))
    return deviations


def _window_median(values: list, index: int) -> int:
    previous = values[index - 1] if index > 0 else values[index]
    following = values[index + 1] if index + 1 < len(values) else values[index]
    return _median3(previous, values[index], following)


def _median3(a: int, b: int, c: int) -> int:
    if a > b:
        a, b = b, a
    if b > c:
        b, c = c, b
    if a > b:
        a, b = b, a
    return b


# (deviation-threshold, label, score). Ordered high-to-low so a single
# descending pass assigns both label and score from one decision.
_LEVELS = (
    (12, "severe", 25),
    (6, "moderate", 10),
    (3, "minor", 3),
)


def _tier(deviation: int, hard_limit: int) -> tuple[str, int]:
    """Return (label, score) for a deviation under the given hard limit."""
    if deviation >= hard_limit:
        return "invalid", 100
    for threshold, label, score in _LEVELS:
        if deviation >= threshold:
            return label, score
    return "clean", 0


def classify_spikes(deviations: list, hard_limit: int) -> tuple:
    labels = []
    total = 0
    worst = 0
    for deviation in deviations:
        label, score = _tier(deviation, hard_limit)
        labels.append(label)
        total += score
        if score > worst:
            worst = score
    return labels, total, worst


def _worst_label(worst_score: int) -> str:
    if worst_score >= 100:
        return "invalid"
    for _threshold, label, score in _LEVELS:
        if worst_score >= score:
            return label
    return "clean"


def _label_counts(labels: list) -> dict:
    counts = {"clean": 0, "minor": 0, "moderate": 0, "severe": 0, "invalid": 0}
    for label in labels:
        counts[label] += 1
    return counts


def _trend(values: list) -> str:
    delta = values[-1] - values[0]
    if delta > TREND_TOLERANCE:
        return "rising"
    if delta < -TREND_TOLERANCE:
        return "falling"
    return "stable"


def _longest_run(labels: list) -> int:
    longest = 0
    current = 0
    for label in labels:
        if label == "clean":
            current = 0
        else:
            current = current + 1
            if current > longest:
                longest = current
    return longest


def _verdict(total: int) -> str:
    if total >= 100:
        return "fail"
    if total >= 25:
        return "warn"
    return "pass"


def _summary_line(count: int, gaps: int, worst_score: int, total: int) -> str:
    return f"n={count};gaps={gaps};worst={_worst_label(worst_score)};score={total}"

