export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Season = "low" | "high";
type Category = "standard" | "suite" | "villa" | "cabin";

interface BookingRequest {
  loyaltyYears: number;
  nights: number;
  guests: number;
  season: Season;
  coupon?: string;
}

interface CategoryRule {
  label: Category;
  minNights: number;
  maxNights: number;
  minStay: number;
  base: number;
  highSurcharge: number;
  deposit: number;
  maxGuests: number;
  nightsError: string;
  stayError: string;
  extraFee: (guests: number) => number;
}

const DISCOUNT_LIFETIME = 3;
const DISCOUNT_DENOMINATOR = 10;
const MAX_LOYALTY = Number.MAX_SAFE_INTEGER;

const categoryRules: Record<Category, CategoryRule> = {
  standard: {
    label: "standard",
    minNights: 1,
    maxNights: 14,
    minStay: 0,
    base: 80,
    highSurcharge: 30,
    deposit: 0,
    maxGuests: 2,
    nightsError: "bad nights",
    stayError: "",
    extraFee: () => 0,
  },
  suite: {
    label: "suite",
    minNights: 1,
    maxNights: 21,
    minStay: 0,
    base: 150,
    highSurcharge: 60,
    deposit: 0,
    maxGuests: 4,
    nightsError: "bad nights",
    stayError: "",
    extraFee: (guests) => (guests > 2 ? 25 : 0),
  },
  villa: {
    label: "villa",
    minNights: 1,
    maxNights: 28,
    minStay: 3,
    base: 300,
    highSurcharge: 120,
    deposit: 500,
    maxGuests: 8,
    nightsError: "bad nights",
    stayError: "villa minimum stay",
    extraFee: () => 0,
  },
  cabin: {
    label: "cabin",
    minNights: 1,
    maxNights: 10,
    minStay: 0,
    base: 50,
    highSurcharge: 15,
    deposit: 0,
    maxGuests: 6,
    nightsError: "bad nights",
    stayError: "",
    extraFee: () => 0,
  },
};

function qualifies(coupon?: string, loyaltyYears?: number): boolean {
  return coupon === "VIP" || (loyaltyYears !== undefined && loyaltyYears >= DISCOUNT_LIFETIME);
}

function applyLoyaltyDiscount(total: number, coupon?: string, loyaltyYears?: number): number {
  return qualifies(coupon, loyaltyYears) ? total - Math.floor(total / DISCOUNT_DENOMINATOR) : total;
}

function badRange(value: number, min: number, max: number): boolean {
  return !Number.isInteger(value) || value < min || value > max;
}

function bookingError(req: BookingRequest, rule: CategoryRule): string | undefined {
  if (badRange(req.nights, rule.minNights, rule.maxNights)) {
    return rule.nightsError;
  }
  if (req.nights < rule.minStay) {
    return rule.stayError;
  }
  if (badRange(req.guests, 1, rule.maxGuests)) {
    return "bad guests";
  }
  return undefined;
}

function computeTotal(req: BookingRequest, rule: CategoryRule): number {
  const base = req.season === "high" ? rule.base + rule.highSurcharge : rule.base;
  const subtotal = base * req.nights;
  const discounted = applyLoyaltyDiscount(subtotal, req.coupon, req.loyaltyYears);
  return discounted + rule.extraFee(req.guests) + rule.deposit;
}

function buildResult(req: BookingRequest, rule: CategoryRule): QuoteResult {
  const total = computeTotal(req, rule);
  const policy = qualifies(req.coupon, req.loyaltyYears) ? "flex" : "strict";
  const line = `${rule.label}:${req.nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }

  const req = raw as Record<string, unknown>;

  if (badRange(req.loyaltyYears as number, 0, MAX_LOYALTY)) {
    return { ok: false, error: "bad loyalty" };
  }

  const rule = categoryRules[req.category as Category];
  if (!rule) {
    return { ok: false, error: "unknown category" };
  }

  const booking: BookingRequest = {
    loyaltyYears: req.loyaltyYears as number,
    nights: req.nights as number,
    guests: req.guests as number,
    season: req.season as Season,
    coupon: req.coupon as string | undefined,
  };

  const error = bookingError(booking, rule);
  if (error) {
    return { ok: false, error };
  }
  if (booking.season !== "low" && booking.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  return buildResult(booking, rule);
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  base: number;
  highSurcharge: number;
  maxNights: number;
  maxGuests: number;
  minStay: number;
  minStayError?: string;
  extra: (guests: number) => number;
}

const CATEGORY: Record<string, CategoryConfig> = {
  cabin: {
    base: 50,
    highSurcharge: 15,
    maxNights: 10,
    maxGuests: 6,
    minStay: 1,
    extra: () => 0,
  },
  standard: {
    base: 80,
    highSurcharge: 30,
    maxNights: 14,
    maxGuests: 2,
    minStay: 1,
    extra: () => 0,
  },
  suite: {
    base: 150,
    highSurcharge: 60,
    maxNights: 21,
    maxGuests: 4,
    minStay: 1,
    extra: (guests) => (guests > 2 ? 25 : 0),
  },
  villa: {
    base: 300,
    highSurcharge: 120,
    maxNights: 28,
    maxGuests: 8,
    minStay: 3,
    minStayError: "villa minimum stay",
    extra: () => 500,
  },
};

function badRequest(
  req: Record<string, unknown>,
  cfg: CategoryConfig,
): string | undefined {
  const nights = req.nights as number;
  const guests = req.guests as number;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return "bad loyalty";
  }
  if (!Number.isInteger(nights) || nights < 1 || nights > cfg.maxNights) {
    return "bad nights";
  }
  if (nights < cfg.minStay) {
    return cfg.minStayError ?? "bad nights";
  }
  if (!Number.isInteger(guests) || guests < 1 || guests > cfg.maxGuests) {
    return "bad guests";
  }
  if (req.season !== "low" && req.season !== "high") {
    return "bad season";
  }
  return undefined;
}

function quoteFor(
  category: string,
  cfg: CategoryConfig,
  req: Record<string, unknown>,
): QuoteResult {
  const nights = req.nights as number;
  const guests = req.guests as number;
  const preferred = (req.loyaltyYears as number) >= 3 || req.coupon === "VIP";

  let total = cfg.base * nights + (req.season === "high" ? cfg.highSurcharge * nights : 0);
  if (preferred) {
    total -= Math.floor(total / 10);
  }
  total += cfg.extra(guests);

  const policy = preferred ? "flex" : "strict";
  const line = `${category}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const category = req.category;
  const cfg = typeof category === "string" ? CATEGORY[category] : undefined;
  if (!cfg) {
    return { ok: false, error: "unknown category" };
  }

  const problem = badRequest(req, cfg);
  if (problem) {
    return { ok: false, error: problem };
  }

  return quoteFor(category, cfg, req);
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  label: string;
  maxNights: number;
  minStay: number;
  maxGuests: number;
  baseRate: number;
  highSeasonExtra: number;
  extraGuestFee?: number;
  cleaningFee?: number;
}

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: { label: "standard", maxNights: 14, minStay: 1, maxGuests: 2, baseRate: 80, highSeasonExtra: 30 },
  suite: { label: "suite", maxNights: 21, minStay: 1, maxGuests: 4, baseRate: 150, highSeasonExtra: 60, extraGuestFee: 25 },
  villa: { label: "villa", maxNights: 28, minStay: 3, maxGuests: 8, baseRate: 300, highSeasonExtra: 120, cleaningFee: 500 },
  cabin: { label: "cabin", maxNights: 10, minStay: 1, maxGuests: 6, baseRate: 50, highSeasonExtra: 15 },
};

function isLoyal(req: Record<string, unknown>): boolean {
  return (req.loyaltyYears as number) >= 3 || req.coupon === "VIP";
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const cfg = CATEGORIES[req.category as string];
  if (!cfg) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights as number;
  const guests = req.guests as number;
  const season = req.season;

  if (!Number.isInteger(nights) || nights < 1 || nights > cfg.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (nights < cfg.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!Number.isInteger(guests) || guests < 1 || guests > cfg.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }

  let total = cfg.baseRate * nights;
  if (season === "high") {
    total += cfg.highSeasonExtra * nights;
  }
  if (isLoyal(req)) {
    total -= Math.floor(total / 10);
  }
  if (cfg.extraGuestFee && guests > 2) {
    total += cfg.extraGuestFee;
  }
  if (cfg.cleaningFee) {
    total += cfg.cleaningFee;
  }

  const policy = isLoyal(req) ? "flex" : "strict";
  const line = `${cfg.label}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

