export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  base: number;
  high: number;
  maxNights: number;
  maxGuests: number;
  minStay: number;
  minStayError?: string;
  extraGuestFee: number;
  serviceFee: number;
}

interface Request {
  category: string;
  nights: number;
  guests: number;
  season: string;
  loyaltyYears: number;
  vip: boolean;
  cfg: CategoryConfig;
}

interface Rule {
  test: (r: Record<string, unknown>, cfg?: CategoryConfig) => boolean;
  error: (cfg?: CategoryConfig) => string;
}

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: { base: 80,  high: 30,  maxNights: 14, maxGuests: 2, minStay: 1, extraGuestFee: 0,  serviceFee: 0 },
  suite:    { base: 150, high: 60,  maxNights: 21, maxGuests: 4, minStay: 1, extraGuestFee: 25, serviceFee: 0 },
  villa:    { base: 300, high: 120, maxNights: 28, maxGuests: 8, minStay: 3, minStayError: "villa minimum stay", extraGuestFee: 0, serviceFee: 500 },
  cabin:    { base: 50,  high: 15,  maxNights: 10, maxGuests: 6, minStay: 1, extraGuestFee: 0, serviceFee: 0 },
};

const MAX_SAFE = Number.MAX_SAFE_INTEGER;
const PREMIUM_LOYALTY = 3;

const PRE_CATEGORY_RULES: Rule[] = [
  { test: (r) => validInt(r.loyaltyYears, 0, MAX_SAFE), error: () => "bad loyalty" },
];

const POST_CATEGORY_RULES: Rule[] = [
  { test: (r, c) => validInt(r.nights, 1, c!.maxNights), error: () => "bad nights" },
  { test: (r, c) => (r.nights as number) >= c!.minStay, error: (c) => c!.minStayError ?? "bad nights" },
  { test: (r, c) => validInt(r.guests, 1, c!.maxGuests), error: () => "bad guests" },
  { test: (r) => r.season === "low" || r.season === "high", error: () => "bad season" },
];

function bad(error: string): QuoteResult {
  return { ok: false, error };
}

function validInt(value: unknown, min: number, max: number): boolean {
  return Number.isInteger(value) && (value as number) >= min && (value as number) <= max;
}

function firstFailure(r: Record<string, unknown>, cfg: CategoryConfig | undefined, rules: Rule[]): QuoteResult | null {
  for (const rule of rules) {
    if (!rule.test(r, cfg)) {
      return bad(rule.error(cfg));
    }
  }
  return null;
}

function parseRequest(raw: unknown): QuoteResult | Request {
  if (typeof raw !== "object" || raw === null) {
    return bad("malformed request");
  }
  const r = raw as Record<string, unknown>;

  const pre = firstFailure(r, undefined, PRE_CATEGORY_RULES);
  if (pre) {
    return pre;
  }
  const cfg = CATEGORIES[r.category as string];
  if (!cfg) {
    return bad("unknown category");
  }
  const post = firstFailure(r, cfg, POST_CATEGORY_RULES);
  if (post) {
    return post;
  }

  return {
    category: r.category as string,
    nights: r.nights as number,
    guests: r.guests as number,
    season: r.season,
    loyaltyYears: r.loyaltyYears as number,
    vip: r.coupon === "VIP",
    cfg,
  };
}

function computeQuote(req: Request): QuoteResult {
  const isHigh = req.season === "high";
  const discounted = req.vip || req.loyaltyYears >= PREMIUM_LOYALTY;

  let total = req.cfg.base * req.nights;
  if (isHigh) {
    total += req.cfg.high * req.nights;
  }
  if (discounted) {
    total -= Math.floor(total / 10);
  }
  if (req.guests > 2) {
    total += req.cfg.extraGuestFee;
  }
  total += req.cfg.serviceFee;

  const policy = discounted ? "flex" : "strict";
  const line = `${req.category}:${req.nights}n:${total}:${policy}`;

  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  const req = parseRequest(raw);
  return "error" in req ? req : computeQuote(req);
}

