  config: CategoryConfig
): string | undefined {
  if (config.minStay !== undefined && (req.nights as number) < config.minStay) {
    return config.name + " minimum stay";
  }
}

function validateGuests(
  req: Record<string, unknown>,
  config: CategoryConfig
): string | undefined {
  if (!Number.isInteger(req.guests) || (req.guests as number) < 1) {
    return "bad guests";
  }
  if ((req.guests as number) > config.maxGuests) {
    return "bad guests";
  }
}

function validateSeason(req: Record<string, unknown>): string | undefined {
  if (req.season !== "low" && req.season !== "high") {
    return "bad season";
  }
}

function firstError(validators: Array<() => string | undefined>): string | undefined {
  for (const validate of validators) {
    const err = validate();
    if (err !== undefined) {
      return err;
    }
  }
}

function validateBooking(
  req: Record<string, unknown>
): { ok: true; data: BookingData } | { ok: false; error: string } {
  const loyaltyError = validateLoyalty(req);
  if (loyaltyError !== undefined) {
    return { ok: false, error: loyaltyError };
  }

  const config = CATEGORIES.find((c) => c.name === req.category);
  if (!config) {
    return { ok: false, error: "unknown category" };
  }

  const error = firstError([
    () => validateNights(req, config),
    () => validateMinStay(req, config),
    () => validateGuests(req, config),
    () => validateSeason(req),
  ]);
  if (error !== undefined) {
    return { ok: false, error };
  }

  return {
    ok: true,
    data: {
      config,
      nights: req.nights as number,
      guests: req.guests as number,
      loyaltyYears: req.loyaltyYears as number,
      season: req.season as string,
      coupon: req.coupon as string | undefined,
    },
  };
}

function computeQuote(data: BookingData): number {
  const { config, nights, guests, loyaltyYears, season, coupon } = data;
  let total = config.baseRate * nights;
  if (season === "high") {
    total += config.highSurcharge * nights;
  }
  if (config.discount(loyaltyYears, coupon)) {
    total -= Math.floor(total / 10);
  }
  if (config.guestFee !== undefined && guests > 2) {
    total += config.guestFee;
  }
  if (config.cleaningFee !== undefined) {
    total += config.cleaningFee;
  }
  return total;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const validation = validateBooking(req);
  if (!validation.ok) {
    return { ok: false, error: validation.error };
  }

  const { config, nights, loyaltyYears, coupon } = validation.data;
  const total = computeQuote(validation.data);
  const policy = config.flexPolicy(loyaltyYears, coupon) ? "flex" : "strict";
  const line = `${config.name}:${nights}n:${total}:${policy}`;

  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryRule {
  baseRate: number;
  highSurcharge: number;
  minNights: number;
  maxNights: number;
  minGuests: number;
  maxGuests: number;
  minStay?: number;
  extraGuestFee?: number;
  flatFee?: number;
}

const CATEGORY_RULES: Record<string, CategoryRule> = {
  cabin: {
    baseRate: 50,
    highSurcharge: 15,
    minNights: 1,
    maxNights: 10,
    minGuests: 1,
    maxGuests: 6,
  },
  standard: {
    baseRate: 80,
    highSurcharge: 30,
    minNights: 1,
    maxNights: 14,
    minGuests: 1,
    maxGuests: 2,
  },
  suite: {
    baseRate: 150,
    highSurcharge: 60,
    minNights: 1,
    maxNights: 21,
    minGuests: 1,
    maxGuests: 4,
    extraGuestFee: 25,
  },
  villa: {
    baseRate: 300,
    highSurcharge: 120,
    minNights: 1,
    maxNights: 28,
    minGuests: 1,
    maxGuests: 8,
    minStay: 3,
    flatFee: 500,
  },
};

type Request = {
  category: string;
  loyaltyYears: number;
  nights: number;
  guests: number;
  season: string;
  coupon: unknown;
};

function parseRequest(raw: unknown): { request: Request } | QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  return {
    request: {
      category: req.category as string,
      loyaltyYears: req.loyaltyYears as number,
      nights: req.nights as number,
      guests: req.guests as number,
      season: req.season as string,
      coupon: req.coupon,
    },
  };
}

function hasValidNights(nights: number, rule: CategoryRule): boolean {
  return Number.isInteger(nights) && nights >= rule.minNights && nights <= rule.maxNights;
}

function hasValidGuests(guests: number, rule: CategoryRule): boolean {
  return Number.isInteger(guests) && guests >= rule.minGuests && guests <= rule.maxGuests;
}

function meetsMinStay(nights: number, rule: CategoryRule): boolean {
  return rule.minStay === undefined || nights >= rule.minStay;
}

function hasValidSeason(season: string): boolean {
  return season === "low" || season === "high";
}

function hasKnownCategory(category: string): category is keyof typeof CATEGORY_RULES {
  return category in CATEGORY_RULES;
}

function isEligibleForDiscount(request: Request): boolean {
  return request.coupon === "VIP" || request.loyaltyYears >= 3;
}

function computeTotal(request: Request, rule: CategoryRule): number {
  let total = rule.baseRate * request.nights;
  if (request.season === "high") {
    total += rule.highSurcharge * request.nights;
  }
  if (isEligibleForDiscount(request)) {
    total -= Math.floor(total / 10);
  }
  if (rule.extraGuestFee !== undefined && request.guests > 2) {
    total += rule.extraGuestFee;
  }
  if (rule.flatFee !== undefined) {
    total += rule.flatFee;
  }
  return total;
}

function formatLine(request: Request, total: number, policy: string): string {
  return `${request.category}:${request.nights}n:${total}:${policy}`;
}

export function quoteBooking(raw: unknown): QuoteResult {
  const parsed = parseRequest(raw);
  if ("error" in parsed) {
    return parsed;
  }
  const request = parsed.request;
  if (!hasKnownCategory(request.category)) {
    return { ok: false, error: "unknown category" };
  }
  const rule = CATEGORY_RULES[request.category];

  if (!hasValidNights(request.nights, rule)) {
    return { ok: false, error: "bad nights" };
  }
  if (!meetsMinStay(request.nights, rule)) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!hasValidGuests(request.guests, rule)) {
    return { ok: false, error: "bad guests" };
  }
  if (!hasValidSeason(request.season)) {
    return { ok: false, error: "bad season" };
  }

  const total = computeTotal(request, rule);
  const policy = isEligibleForDiscount(request) ? "flex" : "strict";
  return { ok: true, total, policy, line: formatLine(request, total, policy) };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Season = "low" | "high";

interface CategoryConfig {
  kind: string;
  maxNights: number;
  minStay: number;
  maxGuests: number;
  baseRate: number;
  highAdd: number;
  flatFee: number;
  perExtraGuest: number;
  minStayError: string;
}

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: {
    kind: "standard",
    maxNights: 14,
    minStay: 1,
    maxGuests: 2,
    baseRate: 80,
    highAdd: 30,
    flatFee: 0,
    perExtraGuest: 0,
    minStayError: "bad nights",
  },
  suite: {
    kind: "suite",
    maxNights: 21,
    minStay: 1,
    maxGuests: 4,
    baseRate: 150,
    highAdd: 60,
    flatFee: 0,
    perExtraGuest: 25,
    minStayError: "bad nights",
  },
  villa: {
    kind: "villa",
    maxNights: 28,
    minStay: 3,
    maxGuests: 8,
    baseRate: 300,
    highAdd: 120,
    flatFee: 500,
    perExtraGuest: 0,
    minStayError: "villa minimum stay",
  },
  cabin: {
    kind: "cabin",
    maxNights: 10,
    minStay: 1,
    maxGuests: 6,
    baseRate: 50,
    highAdd: 15,
    flatFee: 0,
    perExtraGuest: 0,
    minStayError: "bad nights",
  },
};

interface BookingInput {
  cfg: CategoryConfig;
  nights: number;
  guests: number;
  loyalty: number;
  season: Season;
  coupon: unknown;
}

type Parsed =
  | { ok: true; input: BookingInput }
  | { ok: false; error: string };

function isSeason(value: unknown): value is Season {
  return value === "low" || value === "high";
}

function badNights(cfg: CategoryConfig, nights: unknown): boolean {
  return !Number.isInteger(nights) || (nights as number) < 1 || (nights as number) > cfg.maxNights;
}

function parseBooking(raw: unknown): Parsed {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  const cfg = CATEGORIES[req.category as string];
  if (!cfg) {
    return { ok: false, error: "unknown category" };
  }
  const nights = req.nights as number;
  const guests = req.guests as number;
  const loyalty = req.loyaltyYears as number;
  if (badNights(cfg, req.nights)) {
    return { ok: false, error: "bad nights" };
  }
  if (nights < cfg.minStay) {
    return { ok: false, error: cfg.minStayError };
  }
  if (!Number.isInteger(req.guests) || guests < 1 || guests > cfg.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (!isSeason(req.season)) {
    return { ok: false, error: "bad season" };
  }
  return { ok: true, input: { cfg, nights, guests, loyalty, season: req.season, coupon: req.coupon } };
}

function nightlyRate(cfg: CategoryConfig, season: Season): number {
  return season === "high" ? cfg.baseRate + cfg.highAdd : cfg.baseRate;
}

function applyDiscount(total: number, loyalty: number, coupon: unknown): number {
  return coupon === "VIP" || loyalty >= 3 ? total - Math.floor(total / 10) : total;
}

function cancellationPolicy(loyalty: number, coupon: unknown): "flex" | "strict" {
  return coupon === "VIP" || loyalty >= 3 ? "flex" : "strict";
}

export function quoteBooking(raw: unknown): QuoteResult {
  const parsed = parseBooking(raw);
  if (!parsed.ok) {
    return { ok: false, error: parsed.error };
  }
  const { cfg, nights, guests, loyalty, season, coupon } = parsed.input;

  const subtotal = applyDiscount(nightlyRate(cfg, season) * nights, loyalty, coupon);
  const total = subtotal + cfg.flatFee + (guests > 2 ? cfg.perExtraGuest : 0);
  const policy = cancellationPolicy(loyalty, coupon);

  return { ok: true, total, policy, line: `${cfg.kind}:${nights}n:${total}:${policy}` };
}

