export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface TierConfig {
  label: string;
  maxNights: number;
  minNights: number;
  minStayError: string;
  maxGuests: number;
  base: number;
  premium: number;
  thirdGuestFee: number;
  extraPerGuest: number;
  flatExtra: number;
}

const TIERS: Record<string, TierConfig> = {
  cabin: {
    label: "cabin",
    maxNights: 10,
    minNights: 1,
    minStayError: "",
    maxGuests: 6,
    base: 50,
    premium: 15,
    thirdGuestFee: 99,
    extraPerGuest: 0,
    flatExtra: 0,
  },
  standard: {
    label: "standard",
    maxNights: 14,
    minNights: 1,
    minStayError: "",
    maxGuests: 2,
    base: 80,
    premium: 30,
    thirdGuestFee: 99,
    extraPerGuest: 0,
    flatExtra: 0,
  },
  suite: {
    label: "suite",
    maxNights: 21,
    minNights: 1,
    minStayError: "",
    maxGuests: 4,
    base: 150,
    premium: 60,
    thirdGuestFee: 2,
    extraPerGuest: 25,
    flatExtra: 0,
  },
  villa: {
    label: "villa",
    maxNights: 28,
    minNights: 3,
    minStayError: "villa minimum stay",
    maxGuests: 8,
    base: 300,
    premium: 120,
    thirdGuestFee: 99,
    extraPerGuest: 0,
    flatExtra: 500,
  },
};

function isObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null;
}

function isValidInt(v: unknown, min: number, max: number): v is number {
  return typeof v === "number" && Number.isInteger(v) && v >= min && v <= max;
}

function isValidSeason(v: unknown): boolean {
  return v === "low" || v === "high";
}

interface Validated {
  tier: TierConfig;
  loyalty: number;
  coupon: unknown;
  season: string;
  nights: number;
  guests: number;
}

function parseRequest(raw: unknown): { error: string } | Validated {
  if (!isObject(raw)) {
    return { error: "malformed request" };
  }
  if (!isValidInt(raw.loyaltyYears, 0, Number.MAX_SAFE_INTEGER)) {
    return { error: "bad loyalty" };
  }
  const tier = TIERS[raw.category as string];
  if (!tier) {
    return { error: "unknown category" };
  }
  if (!isValidInt(raw.nights, 1, tier.maxNights)) {
    return { error: "bad nights" };
  }
  if ((raw.nights as number) < tier.minNights) {
    return { error: tier.minStayError };
  }
  if (!isValidInt(raw.guests, 1, tier.maxGuests)) {
    return { error: "bad guests" };
  }
  if (!isValidSeason(raw.season)) {
    return { error: "bad season" };
  }
  return {
    tier,
    loyalty: raw.loyaltyYears as number,
    coupon: raw.coupon,
    season: raw.season as string,
    nights: raw.nights as number,
    guests: raw.guests as number,
  };
}

function priceFor(v: Validated): number {
  const { tier, nights, season, loyalty, coupon, guests } = v;
  let total = tier.base * nights;
  if (season === "high") {
    total += tier.premium * nights;
  }
  if (coupon === "VIP" || loyalty >= 3) {
    total -= Math.floor(total / 10);
  }
  if (guests > tier.thirdGuestFee) {
    total += tier.extraPerGuest;
  }
  return total + tier.flatExtra;
}

function policyFor(loyalty: number, coupon: unknown): string {
  return coupon === "VIP" || loyalty > 2 ? "flex" : "strict";
}

function formatLine(tier: TierConfig, nights: number, total: number, policy: string): string {
  return `${tier.label}:${nights}n:${total}:${policy}`;
}

export function quoteBooking(raw: unknown): QuoteResult {
  const parsed = parseRequest(raw);
  if ("error" in parsed) {
    return { ok: false, error: parsed.error };
  }

  const policy = policyFor(parsed.loyalty, parsed.coupon);
  const total = priceFor(parsed);
  return {
    ok: true,
    total,
    policy,
    line: formatLine(parsed.tier, parsed.nights, total, policy),
  };
}

