export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Category = "standard" | "suite" | "villa";
type Season = "low" | "high";
type Policy = "strict" | "flex";

interface RateConfig {
  base: number;
  extra: number;
  maxNights: number;
  maxGuests: number;
  minStay?: number;
  guestSurcharge?: number;
  flatFee?: number;
}

const CONFIG: Record<Category, RateConfig> = {
  standard: { base: 80, extra: 30, maxNights: 14, maxGuests: 2 },
  suite: { base: 150, extra: 60, maxNights: 21, maxGuests: 4, guestSurcharge: 25 },
  villa: { base: 300, extra: 120, maxNights: 28, maxGuests: 8, minStay: 3, flatFee: 500 },
};

interface ParsedRequest {
  category: Category;
  loyaltyYears: number;
  nights: number;
  guests: number;
  season: Season;
  privileged: boolean;
}

function invalid(error: string): { valid: false; error: string } {
  return { valid: false, error };
}
function valid(value: ParsedRequest): { valid: true; value: ParsedRequest } {
  return { valid: true, value };
}

type Validation = { valid: boolean } & ({ error: string } | { value: ParsedRequest });

function rangeInt(
  value: unknown,
  min: number,
  max: number,
  error: string,
): number | { error: string } {
  const n = value as number;
  if (!Number.isInteger(n) || n < min || n > max) {
    return { error };
  }
  return n;
}

function parseRequest(raw: unknown): Validation {
  if (typeof raw !== "object" || raw === null) {
    return invalid("malformed request");
  }
  const req = raw as Record<string, unknown>;

  const loyalty = rangeInt(req.loyaltyYears, 0, Infinity, "bad loyalty");
  if ("error" in loyalty) {
    return invalid(loyalty.error);
  }

  const category = req.category as Category;
  const config = CONFIG[category];
  if (!config) {
    return invalid("unknown category");
  }

  const nights = rangeInt(req.nights, 1, config.maxNights, "bad nights");
  if ("error" in nights) {
    return invalid(nights.error);
  }
  if (nights < (config.minStay ?? 1)) {
    return invalid("villa minimum stay");
  }

  const guests = rangeInt(req.guests, 1, config.maxGuests, "bad guests");
  if ("error" in guests) {
    return invalid(guests.error);
  }

  if (req.season !== "low" && req.season !== "high") {
    return invalid("bad season");
  }

  return valid({
    category,
    loyaltyYears: loyalty,
    nights,
    guests,
    season: req.season as Season,
    privileged: req.coupon === "VIP" || loyalty >= 3,
  });
}

function computeTotal(req: ParsedRequest, config: RateConfig): number {
  const nightly = config.base + (req.season === "high" ? config.extra : 0);
  let total = nightly * req.nights;
  if (req.privileged) {
    total -= Math.floor(total / 10);
  }
  if (config.guestSurcharge !== undefined && req.guests > 2) {
    total += config.guestSurcharge;
  }
  if (config.flatFee !== undefined) {
    total += config.flatFee;
  }
  return total;
}

function policyOf(req: ParsedRequest): Policy {
  return req.privileged ? "flex" : "strict";
}

export function quoteBooking(raw: unknown): QuoteResult {
  const parsed = parseRequest(raw);
  if (!parsed.valid) {
    return { ok: false, error: parsed.error };
  }

  const { value } = parsed;
  const total = computeTotal(value, CONFIG[value.category]);
  const policy = policyOf(value);
  const line = `${value.category}:${value.nights}n:${total}:${policy}`;

  return { ok: true, total, policy, line };
}

