import { quoteBooking as orig } from './orig.ts';
import { quoteBooking as neu } from './new.ts';
const cats = ['standard','suite','villa','unknown',''];
const ly = [-1,0,1,2,2.5,3,5];
const nights = [-5,0,1,2,3,4,14,15,21,22,28,29];
const guests = [-1,0,1,2,3,4,8,9];
const seasons = ['low','high','peak',''];
const coupons = ['VIP','GOLD',undefined,5];
let n=0, bad=0;
for (const category of cats)
 for (const loyaltyYears of ly)
  for (const nights_ of nights)
   for (const guests_ of guests)
    for (const season of seasons)
     for (const coupon of coupons){
       const raw = {category, loyaltyYears, nights: nights_, guests: guests_, season, coupon};
       const a = orig(raw), b = neu(raw);
       n++;
       if (JSON.stringify(a) !== JSON.stringify(b)){
         bad++;
         if (bad<=30) console.log('MISMATCH', JSON.stringify(raw), '=> orig', JSON.stringify(a), 'new', JSON.stringify(b));
       }
     }
console.log(`tested ${n}, mismatches ${bad}`);

