interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

function getStock(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function addStock(stock: Record<string, number>, item: string, qty: number): void {
  stock[item] = getStock(stock, item) + qty;
}

function removeStock(stock: Record<string, number>, item: string, qty: number): void {
  stock[item] = getStock(stock, item) - qty;
}

function fillQueue(state: State): void {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    if (getStock(state.stock, want.item) < want.qty) continue;
    removeStock(state.stock, want.item, want.qty);
    state.reserved[pendingId] = { item: want.item, qty: want.qty };
    state.orders[pendingId] = "reserved";
    delete state.pendingWants[pendingId];
    state.queue.splice(position, 1);
    position = position - 1;
  }
}

function hasId(event: Record<string, unknown>): boolean {
  return typeof event.id === "string" && event.id.length > 0;
}

function hasItem(event: Record<string, unknown>): boolean {
  return typeof event.item === "string" && event.item.length > 0;
}

function hasQty(event: Record<string, unknown>): boolean {
  return Number.isInteger(event.qty) && (event.qty as number) >= 1;
}

interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  shipped: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

function orderEvent(state: State, event: Record<string, unknown>): string | null {
  if (!hasId(event)) return "bad id";
  const id = event.id as string;
  if (state.orders[id] !== undefined) return "duplicate order";
  if (!hasItem(event)) return "bad item";
  if (!hasQty(event)) return "bad qty";
  const item = event.item as string;
  const qty = event.qty as number;
  if (getStock(state.stock, item) >= qty) {
    removeStock(state.stock, item, qty);
    state.reserved[id] = { item, qty };
    state.orders[id] = "reserved";
  } else {
    state.queue.push(id);
    state.pendingWants[id] = { item, qty };
    state.orders[id] = "backordered";
  }
  return null;
}

function cancelEvent(state: State, event: Record<string, unknown>): string | null {
  if (!hasId(event)) return "bad id";
  const id = event.id as string;
  if (state.reserved[id] !== undefined) {
    const holding = state.reserved[id];
    addStock(state.stock, holding.item, holding.qty);
    delete state.reserved[id];
    state.orders[id] = "cancelled";
    fillQueue(state);
  } else if (state.orders[id] === "backordered") {
    state.queue.splice(state.queue.indexOf(id), 1);
    delete state.pendingWants[id];
    state.orders[id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function shipEvent(state: State, event: Record<string, unknown>): string | null {
  if (!hasId(event)) return "bad id";
  if (event.qty !== undefined && !hasQty(event)) return "bad qty";
  const id = event.id as string;
  const reservedWant = state.reserved[id];
  if (reservedWant === undefined) {
    state.rejected = state.rejected + 1;
  } else if (event.qty === undefined || (event.qty as number) === reservedWant.qty) {
    addShipped(state, id, reservedWant);
    delete state.reserved[id];
    state.orders[id] = "shipped";
  } else if ((event.qty as number) < reservedWant.qty) {
    addShipped(state, id, { item: reservedWant.item, qty: event.qty as number });
    state.reserved[id].qty = reservedWant.qty - (event.qty as number);
    state.orders[id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function restockEvent(state: State, event: Record<string, unknown>): string | null {
  if (!hasItem(event)) return "bad item";
  if (!hasQty(event)) return "bad qty";
  addStock(state.stock, event.item as string, event.qty as number);
  fillQueue(state);
  return null;
}

function expireEvent(state: State, event: Record<string, unknown>): string | null {
  if (!hasId(event)) return "bad id";
  const id = event.id as string;
  if (state.reserved[id] !== undefined) {
    const holding = state.reserved[id];
    addStock(state.stock, holding.item, holding.qty);
    delete state.reserved[id];
    state.orders[id] = "expired";
    fillQueue(state);
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function addShipped(state: State, id: string, shipped: Want): void {
  const existing = state.shipped[id];
  if (existing === undefined) {
    state.shipped[id] = { item: shipped.item, qty: shipped.qty };
  } else {
    existing.qty = existing.qty + shipped.qty;
  }
}

function returnEvent(state: State, event: Record<string, unknown>): string | null {
  if (!hasId(event)) return "bad id";
  const id = event.id as string;
  if (state.shipped[id] === undefined || state.orders[id] !== "shipped") {
    state.rejected = state.rejected + 1;
  } else {
    const shipped = state.shipped[id];
    addStock(state.stock, shipped.item, shipped.qty);
    delete state.shipped[id];
    state.orders[id] = "returned";
    fillQueue(state);
  }
  return null;
}

const HANDLERS: Record<string, (s: State, e: Record<string, unknown>) => string | null> = {
  order: orderEvent,
  cancel: cancelEvent,
  ship: shipEvent,
  restock: restockEvent,
  expire: expireEvent,
  return: returnEvent,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) return { ok: false, error: "malformed input" };

  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) return { ok: false, error: "bad stock" };
  if (!Array.isArray(input.events)) return { ok: false, error: "bad events" };

  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }

  const state: State = {
    stock,
    orders: {},
    reserved: {},
    shipped: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) return fail(index, "malformed");

    const handler = HANDLERS[event.type as string];
    if (handler === undefined) return fail(index, "bad type");

    const error = handler(state, event);
    if (error !== null) return fail(index, error);
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

function fail(index: number, why: string): FulfillmentResult {
  return { ok: false, error: `event ${index}: ${why}` };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface Context {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  origins: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

function stockOnHand(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function takeStock(stock: Record<string, number>, item: string, qty: number): void {
  stock[item] = stockOnHand(stock, item) - qty;
}

function returnStock(stock: Record<string, number>, item: string, qty: number): void {
  stock[item] = stockOnHand(stock, item) + qty;
}

function fulfillQueue(ctx: Context): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const onHand = stockOnHand(ctx.stock, want.item);
    if (onHand >= want.qty) {
      takeStock(ctx.stock, want.item, want.qty);
      ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
      ctx.orders[pendingId] = "reserved";
      delete ctx.pendingWants[pendingId];
      ctx.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function checkId(event: Record<string, unknown>, index: number): string | null {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  return null;
}

function checkQty(event: Record<string, unknown>, index: number): string | null {
  if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
    return "event " + index + ": bad qty";
  }
  return null;
}

function handleOrder(event: Record<string, unknown>, ctx: Context, index: number): string | null {
  const idError = checkId(event, index);
  if (idError) return idError;
  if (ctx.orders[event.id as string] !== undefined) {
    return "event " + index + ": duplicate order";
  }
  if (typeof event.item !== "string" || event.item.length === 0) {
    return "event " + index + ": bad item";
  }
  const qtyError = checkQty(event, index);
  if (qtyError) return qtyError;

  const origin = { item: event.item as string, qty: event.qty as number };
  ctx.origins[event.id as string] = origin;

  const available = stockOnHand(ctx.stock, event.item as string);
  if (available >= (event.qty as number)) {
    takeStock(ctx.stock, event.item as string, event.qty as number);
    ctx.reserved[event.id as string] = { item: event.item as string, qty: event.qty as number };
    ctx.orders[event.id as string] = "reserved";
  } else {
    ctx.queue.push(event.id as string);
    ctx.pendingWants[event.id as string] = { item: event.item as string, qty: event.qty as number };
    ctx.orders[event.id as string] = "backordered";
  }
  return null;
}

function handleCancel(event: Record<string, unknown>, ctx: Context, index: number): string | null {
  const idError = checkId(event, index);
  if (idError) return idError;
  const id = event.id as string;
  if (ctx.reserved[id] !== undefined) {
    const holding = ctx.reserved[id];
    returnStock(ctx.stock, holding.item, holding.qty);
    delete ctx.reserved[id];
    ctx.orders[id] = "cancelled";
    fulfillQueue(ctx);
  } else if (ctx.orders[id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(id), 1);
    delete ctx.pendingWants[id];
    ctx.orders[id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

function handleShip(event: Record<string, unknown>, ctx: Context, index: number): string | null {
  const idError = checkId(event, index);
  if (idError) return idError;
  if (
    event.qty !== undefined &&
    (!Number.isInteger(event.qty) || (event.qty as number) < 1)
  ) {
    return "event " + index + ": bad qty";
  }
  const id = event.id as string;
  const held = ctx.reserved[id];
  if (held === undefined) {
    ctx.rejected = ctx.rejected + 1;
    return null;
  }
  const shipQty = event.qty === undefined ? held.qty : (event.qty as number);
  if (shipQty > held.qty) {
    ctx.rejected = ctx.rejected + 1;
    return null;
  }
  if (shipQty === held.qty) {
    delete ctx.reserved[id];
    ctx.orders[id] = "shipped";
    return null;
  }
  held.qty -= shipQty;
  ctx.orders[id] = "partial";
  return null;
}

function handleRestock(event: Record<string, unknown>, ctx: Context, index: number): string | null {
  if (typeof event.item !== "string" || event.item.length === 0) {
    return "event " + index + ": bad item";
  }
  const qtyError = checkQty(event, index);
  if (qtyError) return qtyError;
  returnStock(ctx.stock, event.item as string, event.qty as number);
  fulfillQueue(ctx);
  return null;
}

function handleReturn(event: Record<string, unknown>, ctx: Context, index: number): string | null {
  const idError = checkId(event, index);
  if (idError) return idError;
  const id = event.id as string;
  if (ctx.orders[id] !== "shipped") {
    ctx.rejected = ctx.rejected + 1;
    return null;
  }
  const origin = ctx.origins[id];
  returnStock(ctx.stock, origin.item, origin.qty);
  ctx.orders[id] = "returned";
  return null;
}

function handleExpire(event: Record<string, unknown>, ctx: Context, index: number): string | null {
  const idError = checkId(event, index);
  if (idError) return idError;
  const id = event.id as string;
  if (ctx.reserved[id] !== undefined) {
    const holding = ctx.reserved[id];
    returnStock(ctx.stock, holding.item, holding.qty);
    delete ctx.reserved[id];
    ctx.orders[id] = "expired";
    fulfillQueue(ctx);
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

const HANDLERS: Record<
  string,
  (event: Record<string, unknown>, ctx: Context, index: number) => string | null
> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
  return: handleReturn,
};

function parseStock(input: Record<string, unknown>): { stock?: Record<string, number>; error?: string } {
  if (typeof input.stock !== "object" || input.stock === null) {
    return { error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  return { stock };
}

function buildContext(raw: unknown): { ctx?: Context; error?: string } {
  if (typeof raw !== "object" || raw === null) {
    return { error: "malformed input" };
  }
  if (!Array.isArray((raw as Record<string, unknown>).events)) {
    return { error: "bad events" };
  }
  const parsedStock = parseStock(raw as Record<string, unknown>);
  if (parsedStock.error !== undefined) {
    return { error: parsedStock.error };
  }
  return { ctx: { stock: parsedStock.stock as Record<string, number>, orders: {}, reserved: {}, origins: {}, pendingWants: {}, queue: [], rejected: 0 } };
}

export function processEvents(raw: unknown): FulfillmentResult {
  const parsed = buildContext(raw);
  if (parsed.error !== undefined) {
    return { ok: false, error: parsed.error };
  }
  const ctx = parsed.ctx as Context;

  let events = (raw as Record<string, unknown>).events as Record<string, unknown>[];
  for (let index = 0; index < events.length; index++) {
    const event = events[index];
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handler = HANDLERS[event.type as string];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const error = handler(event, ctx, index);
    if (error !== null) {
      return { ok: false, error };
    }
  }

  return buildResult(ctx);
}

function buildResult(ctx: Context): FulfillmentResult {
  return {
    ok: true,
    orders: ctx.orders,
    stock: ctx.stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

