interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface ParsedInput {
  stock: Record<string, number>;
  events: unknown[];
}

interface EventState {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  wants: Record<string, Want>;
  queue: string[];
  tally: { rejected: number };
}

type Handler = (state: EventState, event: Record<string, unknown>, index: number) => string | null;

export function processEvents(raw: unknown): FulfillmentResult {
  const parsed = parseInput(raw);
  if ("error" in parsed) {
    return { ok: false, error: parsed.error };
  }

  const state: EventState = {
    stock: parsed.stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    wants: {},
    queue: [],
    tally: { rejected: 0 },
  };

  for (let index = 0; index < parsed.events.length; index++) {
    const event = parsed.events[index];
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const record = event as Record<string, unknown>;
    const handler = HANDLERS[record.type as string];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const error = handler(state, record, index);
    if (error !== null) {
      return { ok: false, error };
    }
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.tally.rejected,
    report: buildReport(state.orders, state.tally.rejected),
  };
}

function parseInput(raw: unknown): ParsedInput | { error: string } {
  if (typeof raw !== "object" || raw === null) {
    return { error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { error: "bad events" };
  }
  return { stock, events: input.events };
}

function onHand(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function returnStock(state: EventState, want: Want, status: string, id: string): void {
  state.stock[want.item] = onHand(state.stock, want.item) + want.qty;
  delete state.reserved[id];
  state.orders[id] = status;
}

function fillBackorders(state: EventState): void {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    if (onHand(state.stock, want.item) >= want.qty) {
      state.stock[want.item] = onHand(state.stock, want.item) - want.qty;
      state.reserved[pendingId] = { item: want.item, qty: want.qty };
      state.orders[pendingId] = "reserved";
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function handleOrder(state: EventState, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (state.orders[event.id] !== undefined) {
    return "event " + index + ": duplicate order";
  }
  if (typeof event.item !== "string" || event.item.length === 0) {
    return "event " + index + ": bad item";
  }
  if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
    return "event " + index + ": bad qty";
  }
  state.wants[event.id] = { item: event.item, qty: event.qty as number };
  if (onHand(state.stock, event.item) >= (event.qty as number)) {
    state.stock[event.item] = onHand(state.stock, event.item) - (event.qty as number);
    state.reserved[event.id] = { item: event.item, qty: event.qty as number };
    state.orders[event.id] = "reserved";
  } else {
    state.queue.push(event.id);
    state.pendingWants[event.id] = { item: event.item, qty: event.qty as number };
    state.orders[event.id] = "backordered";
  }
  return null;
}

function handleCancel(state: EventState, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (state.reserved[event.id] !== undefined) {
    returnStock(state, state.reserved[event.id], "cancelled", event.id);
    fillBackorders(state);
  } else if (state.orders[event.id] === "backordered") {
    state.queue.splice(state.queue.indexOf(event.id), 1);
    delete state.pendingWants[event.id];
    state.orders[event.id] = "cancelled";
  } else {
    state.tally.rejected += 1;
  }
  return null;
}

function handleShip(state: EventState, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
    return "event " + index + ": bad qty";
  }
  if (state.reserved[event.id] === undefined) {
    state.tally.rejected += 1;
  } else if (event.qty === undefined || (event.qty as number) === state.reserved[event.id].qty) {
    delete state.reserved[event.id];
    state.orders[event.id] = "shipped";
  } else if ((event.qty as number) < state.reserved[event.id].qty) {
    state.reserved[event.id].qty -= event.qty as number;
    state.orders[event.id] = "partial";
  } else {
    state.tally.rejected += 1;
  }
  return null;
}

function handleRestock(state: EventState, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.item !== "string" || event.item.length === 0) {
    return "event " + index + ": bad item";
  }
  if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
    return "event " + index + ": bad qty";
  }
  state.stock[event.item] = onHand(state.stock, event.item) + (event.qty as number);
  fillBackorders(state);
  return null;
}

function handleReturn(state: EventState, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (state.orders[event.id] === "shipped") {
    const want = state.wants[event.id];
    state.stock[want.item] = onHand(state.stock, want.item) + want.qty;
    state.orders[event.id] = "returned";
    fillBackorders(state);
  } else {
    state.tally.rejected += 1;
  }
  return null;
}

function handleExpire(state: EventState, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (state.reserved[event.id] !== undefined) {
    returnStock(state, state.reserved[event.id], "expired", event.id);
    fillBackorders(state);
  } else {
    state.tally.rejected += 1;
  }
  return null;
}

const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
  return: handleReturn,
};

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface Ledger {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pending: Record<string, Want>;
  queue: string[];
  rejected: number;
  orderQty: Record<string, number>;
  shipped: Record<string, Want>;
}

function onHand(ledger: Ledger, item: string): number {
  return ledger.stock[item] === undefined ? 0 : ledger.stock[item];
}

function fulfillQueue(ledger: Ledger): void {
  for (let position = 0; position < ledger.queue.length; position++) {
    const pendingId = ledger.queue[position];
    const want = ledger.pending[pendingId];
    if (onHand(ledger, want.item) >= want.qty) {
      ledger.stock[want.item] = onHand(ledger, want.item) - want.qty;
      ledger.reserved[pendingId] = { item: want.item, qty: want.qty };
      ledger.orders[pendingId] = "reserved";
      delete ledger.pending[pendingId];
      ledger.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function release(ledger: Ledger, id: string, status: string): void {
  const holding = ledger.reserved[id];
  ledger.stock[holding.item] = onHand(ledger, holding.item) + holding.qty;
  delete ledger.reserved[id];
  ledger.orders[id] = status;
  fulfillQueue(ledger);
}

function badId(event: Record<string, unknown>, index: number): string | undefined {
  return typeof event.id === "string" && event.id.length > 0
    ? undefined
    : "event " + index + ": bad id";
}

function badQty(qty: unknown, index: number): string | undefined {
  return Number.isInteger(qty) && (qty as number) >= 1 ? undefined : "event " + index + ": bad qty";
}

function handleOrder(ledger: Ledger, event: Record<string, unknown>, index: number): string | undefined {
  const idErr = badId(event, index);
  if (idErr) return idErr;
  if (ledger.orders[event.id as string] !== undefined) {
    return "event " + index + ": duplicate order";
  }
  if (typeof event.item !== "string" || event.item.length === 0) {
    return "event " + index + ": bad item";
  }
  const qtyErr = badQty(event.qty, index);
  if (qtyErr) return qtyErr;
  if (onHand(ledger, event.item) >= (event.qty as number)) {
    ledger.stock[event.item] = onHand(ledger, event.item) - (event.qty as number);
    ledger.reserved[event.id as string] = { item: event.item as string, qty: event.qty as number };
    ledger.orderQty[event.id as string] = event.qty as number;
    ledger.orders[event.id as string] = "reserved";
  } else {
    ledger.queue.push(event.id as string);
    ledger.pending[event.id as string] = { item: event.item as string, qty: event.qty as number };
    ledger.orderQty[event.id as string] = event.qty as number;
    ledger.orders[event.id as string] = "backordered";
  }
  return undefined;
}

function handleCancel(ledger: Ledger, event: Record<string, unknown>, index: number): string | undefined {
  const idErr = badId(event, index);
  if (idErr) return idErr;
  if (ledger.reserved[event.id as string] !== undefined) {
    release(ledger, event.id as string, "cancelled");
  } else if (ledger.orders[event.id as string] === "backordered") {
    ledger.queue.splice(ledger.queue.indexOf(event.id as string), 1);
    delete ledger.pending[event.id as string];
    ledger.orders[event.id as string] = "cancelled";
  } else {
    ledger.rejected = ledger.rejected + 1;
  }
  return undefined;
}

function handleShip(ledger: Ledger, event: Record<string, unknown>, index: number): string | undefined {
  const idErr = badId(event, index);
  if (idErr) return idErr;
  if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
    return "event " + index + ": bad qty";
  }
  const id = event.id as string;
  const holding = ledger.reserved[id];
  if (holding === undefined) {
    ledger.rejected = ledger.rejected + 1;
    return undefined;
  }
  if (event.qty !== undefined && (event.qty as number) > holding.qty) {
    ledger.rejected = ledger.rejected + 1;
    return undefined;
  }
  const shipping = (event.qty as number) ?? holding.qty;
  if (shipping === holding.qty) {
    delete ledger.reserved[id];
    ledger.orders[id] = "shipped";
    ledger.shipped[id] = { item: holding.item, qty: ledger.orderQty[id] };
    return undefined;
  }
  holding.qty = holding.qty - shipping;
  ledger.orders[id] = "partial";
  return undefined;
}

function handleReturn(ledger: Ledger, event: Record<string, unknown>, index: number): string | undefined {
  const idErr = badId(event, index);
  if (idErr) return idErr;
  const shipped = ledger.shipped[event.id as string];
  if (shipped === undefined) {
    ledger.rejected = ledger.rejected + 1;
    return undefined;
  }
  ledger.stock[shipped.item] = onHand(ledger, shipped.item) + shipped.qty;
  delete ledger.shipped[event.id as string];
  ledger.orders[event.id as string] = "returned";
  fulfillQueue(ledger);
  return undefined;
}

function handleRestock(ledger: Ledger, event: Record<string, unknown>, index: number): string | undefined {
  if (typeof event.item !== "string" || event.item.length === 0) {
    return "event " + index + ": bad item";
  }
  const qtyErr = badQty(event.qty, index);
  if (qtyErr) return qtyErr;
  ledger.stock[event.item] = onHand(ledger, event.item) + (event.qty as number);
  fulfillQueue(ledger);
  return undefined;
}

function handleExpire(ledger: Ledger, event: Record<string, unknown>, index: number): string | undefined {
  const idErr = badId(event, index);
  if (idErr) return idErr;
  if (ledger.reserved[event.id as string] !== undefined) {
    release(ledger, event.id as string, "expired");
  } else {
    ledger.rejected = ledger.rejected + 1;
  }
  return undefined;
}

const HANDLERS: Record<string, (l: Ledger, e: Record<string, unknown>, i: number) => string | undefined> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
  return: handleReturn,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
