  { min: 50, label: "idle", rank: 1 },
  { min: 200, label: "active", rank: 2 },
  { min: 600, label: "loaded", rank: 3, alert: "loaded" },
  { min: 900, label: "critical", rank: 4, alert: "critical" },
];

function bandFor(millivolts: number): SignalBand {
  for (let index = SIGNAL_BANDS.length - 1; index >= 0; index--) {
    if (millivolts >= SIGNAL_BANDS[index].min) {
      return SIGNAL_BANDS[index];
    }
  }
  return SIGNAL_BANDS[0];
}

