    return 3;
  }
  if (label === "active") {
    return 2;
  }
  if (label === "idle") {
    return 1;
  }
  return 0;
}

function recordFlatlineAlerts(alerts: string[], parsed: ParsedReading[]): void {
  let runStart = 0;
  let index = 1;
  const flatlineAlerts: string[] = [];
  while (index <= parsed.length) {
    const same = index < parsed.length &&
      parsed[index].channel === parsed[runStart].channel &&
      parsed[index].millivolts === parsed[runStart].millivolts;
    if (same) {
      index++;
      continue;
    }
    if (index - runStart >= 3) {
      flatlineAlerts.push(parsed[runStart].channel + ":flatline");
    }
    runStart = index;
    index++;
  }
  alerts.push(...flatlineAlerts);
}

function recordAlert(alerts: string[], channel: string, label: string): void {
  if (label === "critical" || label === "negative" || label === "loaded") {
    alerts.push(channel + ":" + label);
  }
}

function recordChannel(channels: Record<string, ChannelSummary>, channel: string, millivolts: number, label: string): void {
  const existing = channels[channel];
  if (existing === undefined) {
    channels[channel] = { count: 1, min: millivolts, max: millivolts, worst: label };
    return;
  }
  existing.count += 1;
  if (millivolts < existing.min) {
    existing.min = millivolts;
  }
  if (millivolts > existing.max) {
    existing.max = millivolts;
  }
  if (severityRank(label) > severityRank(existing.worst)) {
    existing.worst = label;
  }
}

function buildReport(readingCount: number, channelCount: number, alertCount: number, labels: string[]): string {
  let worst = "standby";
  for (const label of labels) {
    if (severityRank(label) > severityRank(worst)) {
      worst = label;
    }
  }
  return `readings=${readingCount};channels=${channelCount};alerts=${alertCount};worst=${worst}`;
}

