from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}
    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}

    sums = {}
    maxes = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation"}
        if "x" not in obs or not isinstance(obs["x"], int):
            return {"ok": False, "error": "bad observation"}
        if "y" not in obs or not isinstance(obs["y"], int):
            return {"ok": False, "error": "bad observation"}
        if "value" not in obs or not isinstance(obs["value"], int):
            return {"ok": False, "error": "bad observation"}
        if "quality" not in obs or not isinstance(obs["quality"], int):
            return {"ok": False, "error": "bad observation"}
        if obs["quality"] < 0 or obs["quality"] > 100:
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        x = obs["x"]
        if x < 0:
            dropped = dropped + 1
            continue
        col = x // cell_size
        if col >= width:
            if x - width * cell_size < tolerance:
                col = width - 1
            else:
                dropped = dropped + 1
                continue

        y = obs["y"]
        if y < 0:
            dropped = dropped + 1
            continue
        row = y // cell_size
        if row >= height:
            if y - height * cell_size < tolerance:
                row = height - 1
            else:
                dropped = dropped + 1
                continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        maxes[key] = max(maxes.get(key, obs["value"]), obs["value"])
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells = _value_rows(sums, maxes, counts, width, height, raw["fill_value"], mode)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _value_rows(sums: dict, maxes: dict, counts: dict, width: int, height: int, fill_value: int, mode: str) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                if mode == "max":
                    cells.append(maxes[key])
                else:
                    cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

files.process_batch.ts:
export interface Reading {
  channel: string;
  unit: string;
  value: number;
  at: number;
}

interface ParsedReading {
  channel: string;
  millivolts: number;
  at: number;
}

interface ChannelSummary {
  count: number;
  min: number;
  max: number;
  worst: string;
}

export interface BatchResult {
  ok: boolean;
  error?: string;
  readings?: number;
  labels?: string[];
  channels?: Record<string, ChannelSummary>;
  alerts?: string[];
  report?: string;
}

const MAX_READINGS = 500;
const SUPPORTED_UNITS = new Set(["uV", "mV", "V"]);
const ALERT_LABELS = new Set(["negative", "critical", "loaded"]);

export function processBatch(raw: unknown): BatchResult {
  const batchError = validateBatch(raw);
  if (batchError !== null) {
    return { ok: false, error: batchError };
  }

  const entries = (raw as { readings: unknown[] }).readings;
  const labels: string[] = [];
  const alerts: string[] = [];
  const channels: Record<string, ChannelSummary> = {};
  let worst = "standby";

  for (let index = 0; index < entries.length; index++) {
    const outcome = parseReading(entries[index], index);
    if (typeof outcome === "string") {
      return { ok: false, error: outcome };
    }

    const { channel, millivolts } = outcome;
    const label = classifySignal(millivolts);
    labels.push(label);

    if (ALERT_LABELS.has(label)) {
      alerts.push(channel + ":" + label);
    }
    if (severityRank(label) > severityRank(worst)) {
      worst = label;
    }

    const existing = channels[channel];
    if (existing === undefined) {
      channels[channel] = { count: 1, min: millivolts, max: millivolts, worst: label };
      continue;
    }
    existing.count = existing.count + 1;
    existing.min = Math.min(existing.min, millivolts);
    existing.max = Math.max(existing.max, millivolts);
    if (severityRank(label) > severityRank(existing.worst)) {
      existing.worst = label;
    }
  }

  appendFlatlineAlerts(entries, alerts);

  const report =
    "readings=" + entries.length +
    ";channels=" + Object.keys(channels).length +
    ";alerts=" + alerts.length +
    ";worst=" + worst;

  return { ok: true, readings: entries.length, labels, channels, alerts, report };
}

function validateBatch(raw: unknown): string | null {
  if (typeof raw !== "object" || raw === null) {
    return "malformed batch";
  }
  const batch = raw as Record<string, unknown>;
  if (!Array.isArray(batch.readings)) {
    return "missing readings";
  }
  if (batch.readings.length === 0) {
    return "empty batch";
  }
  if (batch.readings.length > MAX_READINGS) {
    return "batch too large";
  }
  return null;
}

function parseReading(entry: unknown, index: number): ParsedReading | string {
  if (typeof entry !== "object" || entry === null) {
    return "reading " + index + ": malformed";
  }
  const record = entry as Record<string, unknown>;
  if (typeof record.channel !== "string" || record.channel.length === 0) {
    return "reading " + index + ": bad channel";
  }
  if (!SUPPORTED_UNITS.has(record.unit as string)) {
    return "reading " + index + ": bad unit";
  }
  if (!Number.isInteger(record.value)) {
    return "reading " + index + ": bad value";
  }
  if (!isNonNegativeInt(record.at)) {
    return "reading " + index + ": bad timestamp";
  }
  return {
    channel: record.channel,
    millivolts: normalizeValue(record.unit as string, record.value as number),
    at: record.at as number,
  };
}

function isNonNegativeInt(value: unknown): boolean {
  return Number.isInteger(value) && (value as number) >= 0;
}

function normalizeValue(unit: string, value: number): number {
  if (unit === "V") {
    return value * 1000;
  }
  if (unit === "uV") {
    return Math.trunc(value / 1000);
  }
  return value;
}

export function classifySignal(millivolts: number): string {  if (millivolts >= 0 && millivolts < 50) {
    return "standby";
  }
  if (millivolts >= 50 && millivolts < 200) {
    return "idle";
  }
  if (millivolts >= 200 && millivolts < 600) {
    return "active";
  }
  if (millivolts >= 600 && millivolts < 900) {
    return "loaded";
  }
  if (millivolts >= 900) {
    return "critical";
  }
  return "negative";
}

function appendFlatlineAlerts(entries: unknown[], alerts: string[]): void {
  let runStart = 0;
  while (runStart < entries.length) {
    const first = parseReading(entries[runStart], runStart);
    if (typeof first === "string") {
      runStart++;
      continue;
    }
    let runEnd = runStart + 1;
    while (runEnd < entries.length) {
      const next = parseReading(entries[runEnd], runEnd);
      if (typeof next === "string" || next.channel !== first.channel || next.millivolts !== first.millivolts) {
        break;
      }
      runEnd++;
    }
    if (runEnd - runStart >= 3) {
      alerts.push(first.channel + ":flatline");
    }
    runStart = runEnd;
  }
}

function severityRank(label: string): number {
  if (label === "negative") {
    return 5;
  }
  if (label === "critical") {
    return 4;
  }
  if (label === "loaded") {
    return 3;
  }
  if (label === "active") {
    return 2;
  }
  if (label === "idle") {
    return 1;
  }
  return 0;
}

